/*
 * Stores the generated instruction templates of the night-vision path: the render function that transfers the
 * per-view NV parameters, its four phase functions, the flight world's constructor and render callback, and
 * both post-processing stage gates. These tables are retained compatibility evidence and must stay consistent
 * with the reviewed native implementation.
 */

#pragma once
#include <cstdint>
#include <limits>
#include <string_view>
#include "../relocatable_contract.hpp"

/*
 * Generated by tools/generate-night-vision-model.py from the reviewed Steam 1.8.16.0 code. Complete reviewed
 * bodies; only decoded address operands are masked: calls, jumps and RIP-relative references that leave their
 * function, and image-base-relative table addresses. The Steam and Microsoft Store builds place code and data
 * at different addresses: the operands follow the layout while every other byte stays exact. The render
 * function exceeds one template and is split at an instruction boundary; the caller proves that both parts
 * are adjacent. The caller separately proves boundaries, the override section, RTTI, the callback slot and
 * lifetime.
 */

